def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    if n >= 99:
        return 'D'

    opp_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1

    recent_window = n if n < 10 else 10
    recent_start = n - recent_window
    recent_opp_d = 0
    for i in range(recent_start, n):
        if history[i][1] == 'D':
            recent_opp_d += 1

    punish = 0
    validated = False
    for i in range(1, n):
        pa, pb = history[i - 1]
        ca, cb = history[i]
        if pa == 'D' and pb == 'C' and cb == 'D':
            punish += 1
        if pa == 'D' and pb == 'C' and ca == 'C' and cb == 'C':
            validated = True

    if opp_d == n:
        return 'D'

    if recent_opp_d >= 5 or opp_d * 10 > n * 6:
        return 'D'

    if n >= 10 and recent_opp_d == 0 and punish == 0 and opp_d <= max(8, n // 2):
        if opp_last == 'C':
            if my_last == 'D':
                if validated:
                    return 'D'
                return 'C'
            return 'D'

    if opp_last == 'D':
        if my_last == 'C':
            if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
                return 'C'
            return 'D'
        if recent_opp_d >= 4:
            return 'D'
        return 'C'

    if my_last == 'D':
        return 'C'

    return 'C'
